package observe

import (
	"bytes"
	"encoding/json"
	"os"
	"testing"
)

// The expected bytes and hashes must be generated by the real Python json_bytes.
func TestPythonMemberBytesInterop(t *testing.T) {
	path := os.Getenv("INFERYARD_TEST_MEMBER_CORPUS")
	if path == "" {
		t.Skip("explicit Python-generated canonical corpus required")
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var cases []struct {
		Name     string          `json:"name"`
		Input    json.RawMessage `json:"input"`
		Expected string          `json:"expected"`
		SHA256   string          `json:"sha256"`
	}
	if err := StrictJSON(raw, &cases); err != nil || len(cases) < 100 {
		t.Fatal("invalid or incomplete Python corpus", err)
	}
	for _, item := range cases {
		t.Run(item.Name, func(t *testing.T) {
			var value any
			if err := StrictJSON(item.Input, &value); err != nil {
				t.Fatal(err)
			}
			canonical, err := memberBytes(item.Input)
			if err != nil || !bytes.Equal(canonical, []byte(item.Expected)) ||
				digest(canonical) != item.SHA256 {
				t.Fatalf("input=%s\nactual=%s\nexpected=%s\nerror=%v", item.Input, canonical, item.Expected, err)
			}
			if len(canonical) == 0 || canonical[len(canonical)-1] != '\n' ||
				digest(bytes.TrimSuffix(canonical, []byte("\n"))) == item.SHA256 {
				t.Fatal("Python trailing LF is part of the member hash")
			}
		})
	}
}
